// People. The crew members are made up for the example; their pre-flight levels are example
// numbers chosen by Claude. Tom and Elly are the names from the team's own example about personal
// norms (translated from the team's Russian: "Tom's resting heart rate is 70 on Earth and 60 in space;
// Elly's is 80 and 60"); their numbers are kept as that example and are not used for comparison yet
// (which norm to use is an open question). Ids carry no personal information: data files are named by id,
// as NASA asks for ISS research data.
export const CREW = [
  { id: 'crew-1', name: 'Tom', sex: 'M', real: false, baselines: { vo2max: 42, strength: 150 }, pulseExample: { earth: 70, space: 60 } },
  { id: 'crew-2', name: 'Elly', sex: 'F', real: false, baselines: { vo2max: 38, strength: 110 }, pulseExample: { earth: 80, space: 60 } },
  { id: 'crew-3', name: 'Crew member 3', sex: null, real: false, baselines: { vo2max: 40, strength: 140 } },
  { id: 'crew-4', name: 'Crew member 4', sex: null, real: false, baselines: { vo2max: 36, strength: 100 } },
];

// The ship itself: cabin air readings belong to the ship, not to one person.
export const SHIP = { id: 'ship', name: 'Ship: cabin air', real: false, vehicle: true, baselines: {} };

// The four Inspiration4 participants are real people, anonymised by NASA (C001 to C004).
// Only their real blood tests are used, and they are never attached to the made-up crew.
export const realPeople = (subjects) => Object.entries(subjects).map(([code, s]) => ({
  id: `i4-${code.toLowerCase()}`, code, name: `Inspiration4 participant ${code}`, sex: s.sex, real: true, baselines: {},
}));

